package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

/** Notifier: sends marketing offers queued by the customer service. A "send" is a row in `sent`. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, "
                    + "offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            // These tables are additive so an older notifier can continue using sent unchanged.
            s.execute("CREATE TABLE IF NOT EXISTS capped(customer_id VARCHAR(40) PRIMARY KEY, dropped BIGINT NOT NULL)");
            s.execute("CREATE TABLE IF NOT EXISTS offer_customer_lock(customer_id VARCHAR(40) PRIMARY KEY)");
        }
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"offer.queued".equals(topic)) return;
        String customerId = ev.get("customerId");
        long now = ctx.now();
        long dayStart = Math.floorDiv(now, 100) * 100;
        boolean autoCommit = db.getAutoCommit();
        db.setAutoCommit(false);
        try {
            // Serialize new-version consumers for a customer. Existing sent rows are
            // deliberately counted, including rows written by an older version.
            try (PreparedStatement lock = db.prepareStatement(
                    "MERGE INTO offer_customer_lock(customer_id) KEY(customer_id) VALUES (?)")) {
                lock.setString(1, customerId);
                lock.executeUpdate();
            }
            try (PreparedStatement lock = db.prepareStatement(
                    "SELECT customer_id FROM offer_customer_lock WHERE customer_id = ? FOR UPDATE")) {
                lock.setString(1, customerId);
                lock.executeQuery().close();
            }

            int sentToday;
            try (PreparedStatement q = db.prepareStatement(
                    "SELECT COUNT(*) FROM sent WHERE customer_id = ? AND ts >= ? AND ts < ?")) {
                q.setString(1, customerId);
                q.setLong(2, dayStart);
                q.setLong(3, dayStart + 100);
                try (ResultSet rs = q.executeQuery()) { rs.next(); sentToday = rs.getInt(1); }
            }
            if (sentToday < 2) {
                try (PreparedStatement ins = db.prepareStatement(
                        "INSERT INTO sent(customer_id, offer_id, ts) VALUES (?,?,?)")) {
                    ins.setString(1, customerId);
                    ins.setString(2, ev.get("offerId"));
                    ins.setLong(3, now);
                    ins.executeUpdate();
                }
            } else {
                try (PreparedStatement upsert = db.prepareStatement(
                        "MERGE INTO capped(customer_id, dropped) KEY(customer_id) VALUES (?, 0)")) {
                    upsert.setString(1, customerId);
                    upsert.executeUpdate();
                }
                try (PreparedStatement increment = db.prepareStatement(
                        "UPDATE capped SET dropped = dropped + 1 WHERE customer_id = ?")) {
                    increment.setString(1, customerId);
                    increment.executeUpdate();
                }
            }
            db.commit();
        } catch (Exception e) {
            db.rollback();
            throw e;
        } finally {
            db.setAutoCommit(autoCommit);
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM sent")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "sent": return sent(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** Messages sent to a customer: count, ticks, and total offers dropped by the cap. */
    private Map<String, String> sent(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT ts FROM sent WHERE customer_id = ? ORDER BY id")) {
            q.setString(1, req.get("customerId"));
            StringBuilder ticks = new StringBuilder();
            int n = 0;
            try (ResultSet rs = q.executeQuery()) {
                while (rs.next()) { if (n++ > 0) ticks.append(','); ticks.append(rs.getLong(1)); }
            }
            long capped = 0;
            try (PreparedStatement cappedQuery = db.prepareStatement("SELECT dropped FROM capped WHERE customer_id = ?")) {
                cappedQuery.setString(1, req.get("customerId"));
                try (ResultSet rs = cappedQuery.executeQuery()) { if (rs.next()) capped = rs.getLong(1); }
            }
            return Map.of("count", String.valueOf(n), "ticks", ticks.toString(), "capped", String.valueOf(capped));
        }
    }
}
