package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    @Test
    void queuedOfferIsSent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 7;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("1", r.get("count"));
        assertEquals("7", r.get("ticks"));
        assertEquals("0", r.get("capped"));
    }

    @Test
    void capsOffersPerCustomerAndResetsAtTheNextDay() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 199;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o2"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o3"));
        Map<String, String> capped = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("2", capped.get("count"));
        assertEquals("199,199", capped.get("ticks"));
        assertEquals("1", capped.get("capped"));

        c.tick = 200;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o4"));
        assertEquals("3", m.handle("sent", Map.of("customerId", "c1")).get("count"));
        assertEquals("1", m.handle("sent", Map.of("customerId", "c1")).get("capped"));
    }

    @Test
    void healthIsUp() throws Exception {
        Main m = new Main();
        m.start(new FakeContext());
        assertEquals("UP", m.handle("health", Map.of()).get("status"));
    }
}
